text:
  get disabled() {
    return this.#disabled;
  }

  set disabled(val) {
    this.#disabled = val;
    this.toggleForwardDisabled(val);
    const customAction = this.querySelector("#custom");
    if (!customAction.hidden) {
      customAction.disabled = val;
    }
  }
}

